        $rest=$ranked;array_splice($rest,$i,1);$pairs=ygo_workflow_pair($rest,$forbidden,$budget);
        if($pairs!==null)return array_merge([[$a,$b]],$pairs);
    }
    return null;
}

ygo_workflow_ladder_order.body:
{
    $ids=$s['roster'];
