ygo_workflow_recovery_plan.body:
{
    if (!empty($state['complete']) || empty($state['pending']) || empty($state['history']) || $state['round'] < 2) {
        throw new InvalidArgumentException('Solo se puede revertir la ultima fase pendiente de un evento abierto.');
    }
    $replay = ygo_workflow_begin($state['policy']['model'], $state['roster']);
    if ($replay['policy'] !== $state['policy']) throw new InvalidArgumentException('La version del reglamento no permite reconstruir esta fase.');
    $grouped = [];
    foreach ($state['history'] as $m) $grouped[$m['round']][] = $m;
    for ($round=1; $round < $state['round']; $round++) {
        $next = ygo_workflow_next($replay);
        $stored = $grouped[$round] ?? [];
        if ($next['complete'] || count($next['matches']) !== count($stored)) throw new InvalidArgumentException('El historial no coincide con el reglamento; se conserva sin modificarlo.');
        foreach ($next['matches'] as $i=>$m) {
            foreach (['a','b','phase','side','round','group'] as $key) {
                if ($m[$key] !== $stored[$i][$key]) throw new InvalidArgumentException('Los cruces historicos no coinciden con el reglamento.');
            }
        }
        $replay = $next['state'];
        $replay['pending'] = array_map(static function(array $m): array { unset($m['winner'], $m['game_difference']); return $m; }, $stored);
        if ($round === $state['round'] - 1) {
            $replay['schedule'] = $state['schedule'];
            if(isset($state['teams']))$replay['teams']=$state['teams'];
            return ['state'=>$replay,'remove_ids'=>array_map('intval',array_column($state['pending'],'match_id')),'restore_ids'=>array_map('intval',array_column($stored,'match_id'))];
        }
        $replay = ygo_workflow_accept($replay, $stored);
    }
    throw new InvalidArgumentException('No existe una fase anterior que recuperar.');
}

ygo_qualification_candidates.body:
{
    $mode=(string)($row['mode']??'');$ranking=$source['ranking']??[];
    if(!in_array($mode,['winner','runner_up','top_n','percentage','minimum_points','best_record','group_position'],true))throw new InvalidArgumentException('Criterio de clasificacion desconocido.');
    if(!empty($source['grouped']) && $mode!=='group_position')throw new InvalidArgumentException('Grupos sin final requiere seleccionar Posicion de grupo; no existe una tabla general.');
    $threshold=filter_var($row['threshold']??0,FILTER_VALIDATE_INT);
    if($threshold===false || $threshold<0 || $threshold>1000000)throw new InvalidArgumentException('El umbral debe ser un entero entre 0 y 1000000.');
    if($mode==='winner' || $mode==='runner_up'){
        $id=(int)($source[$mode==='winner'?'champion_id':'runner_up_id']??0);
        if(!$id || !in_array($id,array_map('intval',array_column($ranking,'id')),true))throw new InvalidArgumentException('La fuente no tiene '.($mode==='winner'?'campeon':'subcampeon').' verificable.');
        return array_values(array_filter($ranking,static fn($r)=>(int)$r['id']===$id));
    }
    if($mode==='minimum_points')$ranking=array_values(array_filter($ranking,static fn($r)=>(int)($r['pts']??$r['points']??0)>=$threshold));
    if($mode==='group_position'){
        if($threshold<1 || empty($source['grouped']))throw new InvalidArgumentException('Selecciona una posicion positiva de una fuente con grupos verificados.');
        $ranking=array_values(array_filter($ranking,static fn($r)=>(int)($r['group_position']??0)===$threshold));
    }
    if($mode==='best_record'){
        foreach($ranking as $i=>&$r){
            $r['_qualification_seed']=$i;
            if((int)($r['pj']??0)<1)throw new InvalidArgumentException('Mejor record requiere encuentros disputados y victorias verificables.');
        }unset($r);
        usort($ranking,static fn($a,$b)=>((int)$b['pg']*(int)$a['pj'])<=>((int)$a['pg']*(int)$b['pj'])
            ?: (int)$a['pp']<=>(int)$b['pp'] ?: $a['_qualification_seed']<=>$b['_qualification_seed']);
        foreach($ranking as &$r)unset($r['_qualification_seed']);unset($r);
    }
    return $ranking;
}

ygo_team_lineups.body:
{
    if(!in_array($kind,['team','tag'],true) || count($rows)<2 || count($rows)>64)throw new InvalidArgumentException('Configura entre 2 y 64 equipos.');
