    $alive=array_keys(array_filter($s['players'],static fn($p)=>!$p['eliminated']));
    if(count($alive)===1){$s['status']='FINALIZADA';$s['winner']=$s['players'][$alive[0]]['deck_id'];$s['phase']='FINISHED';}
